/usr/bin/zsh -lc "node <<'NODE'
const fs = require('fs');
const path = 'src/transport/ws/messageHandler.test.ts';
const titles = new Map();
fs.readFileSync(path, 'utf8').split('\\n').forEach((line, i) => {
  const match = line.match(/"'^'"\\s*(?:[fx]?it|[fx]?test)\\(\\s*'(["'^'"']+)'/);
  if (match) titles.set(match[1], i + 1);
});
const files = fs.readdirSync('specs', {withFileTypes: true})
  .filter(entry => entry.isDirectory())
  .map(entry => "'`specs/${entry.name}/spec.md`)
  .filter(file => fs.existsSync(file));
let patch = '"'*** Begin Patch\\n';
let count = 0;
for (const file of files) {
  const old = fs.readFileSync(file, 'utf8');
  const lines = old.split('\\n');
  const changed = lines.map(line => line.replace(/\\[validated by(?:: (["'^'"\\]]+))?\\]\\((["'^)]*src'"\\/transport\\/ws\\/messageHandler\\.test\\.ts)#L\\d+\\)/g, (whole, title, target) => {
    const targetLine = title && titles.get(title);
    return targetLine ? "'`[validated by: ${title}](${target}#L${targetLine})` : whole;
  }));
  const hunks = lines.map((line, i) => line === changed[i] ? null : {line, next: changed[i]}).filter(Boolean);
  if (hunks.length) {
    patch += `*** Update File: ${file}'"\\n"'`;
    for (const {line, next} of hunks) patch += `@@'"\\n-"'${line}'"\\n+"'${next}'"\\n"'`;
    count += hunks.length;
  }
}
patch += '"'*** End Patch\\n';
process.stderr.write("'`changes=${count}'"\\n"'`);
process.stdout.write(patch);
NODE'

